# Strings for the "Why this exists" page (site/why/ and per language). Merged into EXTRA by
# build_pages.rb. Written by the founder; keep the voice plain and first-person plural.
WHY = {
  "en" => {
    why: "Why this exists", why_h: "Why AI Threat Watch exists",
    why_lede: "Artificial intelligence is one of the most useful technologies of our lifetime. Like every powerful technology before it, it is also being turned against people. This site exists so that nobody has to learn that the hard way.",
    why_1h: "The harm is real and it is happening now",
    why_1p: "Voice clones empty bank accounts. Deepfakes move elections and markets. Autonomous agents break into government portals and company networks in hours. Poisoned packages ride into AI toolchains and steal the keys to the cloud. None of this is theoretical: every case file on this site is a documented incident with named sources, and the wire adds new reports every 30 minutes.",
    why_2h: "The record was scattered, so every victim started from zero",
    why_2p: "Until now the evidence lived in vendor blogs, court filings, agency advisories and local press in a dozen languages. A bank in Jordan, a hospital in Spain and a newsroom in Brazil could each be hit by the same technique and never know the others existed. A threat that is already documented should never surprise anyone twice.",
    why_3h: "Our vision",
    why_3p: "The benefits of AI are worth defending, and defending them starts with awareness of how it is being misused. We document every incident precisely, separate what is verified from what is merely reported, and put the evidence in the open so that solutions can come from collective thinking: researchers, defenders, journalists and citizens working from the same facts, so that AI can be used responsibly. The aim is simple: protect future generations from disasters caused by AI, build it responsibly, and safeguard our communities. Fear is not the goal. Preparation is.",
    why_4h: "What we do about it",
    why_4p: "We gather every publicly reported AI security incident, attacks on AI systems and attacks carried out with AI, in near real time from more than fifty vetted sources. Each one is verified and filed as a permanent case file with its sources, severity, timeline and attribution, published in English, French, Spanish, Arabic and Chinese, and released as open data under CC BY 4.0 so anyone can build on it.",
    why_5h: "Who it is for",
    why_5p: "Journalists who need a verifiable record before they publish. Security teams who want to know which technique is being used against organisations like theirs this week. Finance and risk executives who have to price the exposure. Researchers and policymakers who need a dataset rather than anecdotes. And every community that deserves a warning before the disaster, not an explanation after it.",
    why_6h: "Who is behind it",
    why_6p: "AI Threat Watch is an independent project started in 2026 by Karl Abou Zeid. It is independent: no company pays for a case file, a rating or a mention, and no incident is left out or softened for money. The research, triage and translations are done with AI tools; we say so because a site about the misuse of AI should be transparent about its own use of it.",
    why_7h: "How you can help",
    why_7p: "Report an incident we have missed, correct one we got wrong, subscribe to the alerts, reuse the data, or tell someone who needs it. Every contribution makes the next attack a little less likely to succeed.",
